from pathlib import Path
import json, numpy as np, pandas as pd
CLASSES=["BENIGN","SYN_FLOOD","UDP_FLOOD","SLOW_HTTP","DNS_TUNNEL","DGA","C2_BEACON"]
def build(root:Path):
    rng=np.random.default_rng(26145); rows=[]; base=pd.Timestamp("2026-09-01T10:00:00Z")
    for c in CLASSES:
        for i in range(1000):
            proto={"BENIGN":rng.choice(["TCP","UDP","TLS","DNS","QUIC"]),"SYN_FLOOD":"TCP","UDP_FLOOD":"UDP","SLOW_HTTP":"TCP","DNS_TUNNEL":"DNS","DGA":"DNS","C2_BEACON":rng.choice(["TCP","TLS","QUIC"])}[c]
            if c=="BENIGN": duration=float(rng.lognormal(2,.8)); packets=int(rng.integers(8,280)); pmean=float(rng.normal(780,180)); pstd=float(abs(rng.normal(180,70))); iat=float(rng.lognormal(-1,.7)); src="10.10.%d.%d"%(rng.integers(0,20),rng.integers(2,254)); dst="10.20.%d.%d"%(rng.integers(0,20),rng.integers(2,254)); dport=int(rng.choice([53,80,443,8080,22])); severity="Low"; conf=float(rng.uniform(.05,.25)); periodic=float(rng.uniform(.05,.35)); den=float(rng.uniform(2,4)); de=float(rng.normal(3.3,.5)) if proto=="DNS" else 0; qlen=int(rng.integers(8,28)) if proto=="DNS" else 0; ng=float(rng.uniform(.1,.45)) if proto=="DNS" else 0; qrate=float(rng.uniform(.1,10)) if proto=="DNS" else 0
            elif c=="SYN_FLOOD": duration=float(rng.uniform(2,30)); packets=int(rng.integers(800,3500)); pmean=float(rng.normal(64,10)); pstd=float(rng.uniform(4,20)); iat=float(rng.uniform(.001,.03)); src="10.30.%d.%d"%(rng.integers(0,30),rng.integers(2,254)); dst="10.40.0.10"; dport=443; severity=rng.choice(["High","Critical"],p=[.6,.4]); conf=float(rng.uniform(.9,.997)); periodic=float(rng.uniform(0,.08)); den=float(rng.uniform(2,3)); de=0; qlen=ng=qrate=0
            elif c=="UDP_FLOOD": duration=float(rng.uniform(1,20)); packets=int(rng.integers(1200,5000)); pmean=float(rng.normal(900,180)); pstd=float(rng.uniform(40,180)); iat=float(rng.uniform(.0005,.02)); src="10.31.%d.%d"%(rng.integers(0,30),rng.integers(2,254)); dst="10.41.0.10"; dport=int(rng.choice([53,123,443,500])); severity=rng.choice(["High","Critical"],p=[.55,.45]); conf=float(rng.uniform(.91,.998)); periodic=float(rng.uniform(0,.1)); den=float(rng.uniform(1,2)); de=0; qlen=ng=qrate=0
            elif c=="SLOW_HTTP": duration=float(rng.uniform(80,900)); packets=int(rng.integers(30,240)); pmean=float(rng.normal(180,50)); pstd=float(rng.uniform(15,60)); iat=float(rng.uniform(1.5,12)); src="10.32.%d.%d"%(rng.integers(0,10),rng.integers(2,254)); dst="10.42.0.20"; dport=80; severity=rng.choice(["Medium","High"],p=[.6,.4]); conf=float(rng.uniform(.82,.96)); periodic=float(rng.uniform(.2,.55)); den=1; de=0; qlen=ng=qrate=0
            elif c=="DNS_TUNNEL": duration=float(rng.uniform(10,120)); packets=int(rng.integers(40,350)); pmean=float(rng.normal(180,35)); pstd=float(rng.uniform(20,70)); iat=float(rng.uniform(.12,.8)); src="10.33.%d.%d"%(rng.integers(0,10),rng.integers(2,254)); dst="10.53.0.53"; dport=53; severity=rng.choice(["High","Critical"],p=[.7,.3]); conf=float(rng.uniform(.9,.995)); periodic=float(rng.uniform(.2,.7)); den=1; de=float(rng.uniform(4.8,6.6)); qlen=int(rng.integers(32,72)); ng=float(rng.uniform(.72,.99)); qrate=float(rng.uniform(12,250))
            elif c=="DGA": duration=float(rng.uniform(10,180)); packets=int(rng.integers(20,240)); pmean=float(rng.normal(150,40)); pstd=float(rng.uniform(20,70)); iat=float(rng.uniform(.3,2.5)); src="10.34.%d.%d"%(rng.integers(0,10),rng.integers(2,254)); dst="10.53.0.53"; dport=53; severity=rng.choice(["Medium","High"],p=[.45,.55]); conf=float(rng.uniform(.84,.98)); periodic=float(rng.uniform(.1,.55)); den=1; de=float(rng.uniform(4.2,6.1)); qlen=int(rng.integers(18,48)); ng=float(rng.uniform(.58,.95)); qrate=float(rng.uniform(2,80))
            else: duration=float(rng.uniform(60,1200)); packets=int(rng.integers(30,220)); pmean=float(rng.choice([110,120,130,140,900])+rng.normal(0,10)); pstd=float(rng.uniform(5,60)); iat=float(rng.normal(20,1.2)); src="10.35.%d.%d"%(rng.integers(0,10),rng.integers(2,254)); dst="10.60.%d.%d"%(rng.integers(0,5),rng.integers(2,254)); dport=443; severity=rng.choice(["Medium","High","Critical"],p=[.35,.55,.1]); conf=float(rng.uniform(.86,.98)); periodic=float(rng.uniform(.78,.99)); den=1; de=0; qlen=ng=qrate=0
            total_bytes=max(512,int(packets*pmean)); rate=packets/max(duration,.1); byte_rate=total_bytes/max(duration,.1); outbound=int(total_bytes*rng.uniform(.7,1.05)); inbound=max(1,int(total_bytes*rng.uniform(.05,.8 if c!="BENIGN" else 1.3)))
            row={"timestamp":(base+pd.to_timedelta(len(rows),unit="s")).isoformat(),"flow_id":f"FLOW-{len(rows)+1:07d}","src_ip":src,"dst_ip":dst,"src_port":int(rng.integers(1024,64511)),"dst_port":dport,"protocol":str(proto),"flow_duration":round(duration,4),"total_packets":packets,"total_bytes":total_bytes,"packet_rate":round(rate,4),"byte_rate":round(byte_rate,4),"forward_packets":packets,"backward_packets":0,"packet_size_mean":round(pmean,4),"packet_size_std":round(pstd,4),"packet_size_min":round(max(40,pmean-2*pstd),4),"packet_size_max":round(pmean+2*pstd,4),"inter_arrival_time":round(iat,5),"iat_std":round(abs(iat*rng.uniform(.05,.4)),5),"tcp_syn":int(c=="SYN_FLOOD"),"tcp_ack":int(proto in ["TCP","TLS"] and c!="SYN_FLOOD"),"tcp_rst":int(rng.integers(0,3)) if proto=="TCP" else 0,"tcp_fin":int(rng.integers(0,2)) if proto=="TCP" else 0,"source_ip_entropy":round(float(rng.uniform(2,6.5)),4),"destination_ip_entropy":round(float(rng.uniform(1,4)),4),"unique_destination_hosts":int(den),"unique_destination_ports":int(1 if c in ["DNS_TUNNEL","DGA","SYN_FLOOD","UDP_FLOOD","C2_BEACON"] else rng.integers(1,5)),"fanout":int(den),"scan_rate":round(float(den/max(duration,.1)),4),"dns_query_count":int(packets if proto=="DNS" else 0),"unique_domains":int(max(1,packets//10)) if proto=="DNS" else 0,"dns_query_length":qlen,"dns_entropy":round(float(de),4),"nxdomain_ratio":round(float(rng.uniform(0,.3)) if proto=="DNS" else 0,4),"dns_query_rate":round(float(qrate),4),"periodicity_score":round(float(periodic),4),"dominant_frequency_hz":round(1/max(iat,.001),6),"ja3":"lab-ja3-c2" if c=="C2_BEACON" and proto in ["TLS","QUIC"] else "unknown","ja4":"lab-ja4-c2" if c=="C2_BEACON" and proto in ["TLS","QUIC"] else "unknown","tls_version":"TLS1.3" if proto=="TLS" else "","quic_version":"1" if proto=="QUIC" else "","outbound_bytes":outbound,"inbound_bytes":inbound,"outbound_inbound_ratio":round(outbound/inbound,4),"volume_asymmetry":round(abs(outbound-inbound)/max(outbound+inbound,1),4),"label":c,"attack_type":c if c!="BENIGN" else "BENIGN","severity":severity,"ground_truth_confidence":round(conf,4),"source":"lab_generated"}
            rows.append(row)
    df=pd.DataFrame(rows)
    out=root/'data/processed/lab_generated_unidirectional_flows.csv'; out.parent.mkdir(parents=True,exist_ok=True); df.to_csv(out,index=False)
    manifest={'dataset_name':'Uni-Gap Lab Generated Unidirectional Flow Dataset v1','dataset_type':'synthetic_lab_flow','rows':len(df),'classes':{c:int((df.label==c).sum()) for c in CLASSES},'columns':list(df.columns),'reproducible_seed':26145}
    m=root/'data/manifests/lab_generated_unidirectional_v1.json'; m.parent.mkdir(parents=True,exist_ok=True); m.write_text(json.dumps(manifest,indent=2),encoding='utf-8')
    return out, manifest
